var n := 0
for gid in ["U_BLOOD_CLAWS_A", "U_WOLF_PRIEST_A"]:
	for m in GameState.get_unit(gid).models:
		if m.get("alive", true):
			n += int(m.current_wounds)
print("[sw11e-s4] healing balms: wounds before = ", n)
return n

var n := 0
var alive := 0
for gid in ["U_BLOOD_CLAWS_A", "U_WOLF_PRIEST_A"]:
	for m in GameState.get_unit(gid).models:
		if m.get("alive", true):
			n += int(m.current_wounds)
			alive += 1
print("[sw11e-s4] healing balms: wounds after = ", n, " alive models ", alive)
return n - 19 >= 2 and n - 19 <= 4

var u = GameState.get_unit("U_WOLF_GUARD_BATTLE_LEADER_A")
for m in u.models:
	m.position = {"x": 40.0 * 40.0, "y": 55.0 * 40.0}
var w = GameState.get_unit("U_FENRISIAN_WOLVES_A")
MissionManager.check_all_objectives(false)
MissionManager.refresh_objective_control_display()
return "%d,%d" % [MissionManager.model_oc(w, w.models[0]), int(MissionManager.objective_control_state.get("obj_center", 0))]

DebugLogger._flush_buffer()
var f = FileAccess.open(DebugLogger.get_real_log_file_path(), FileAccess.READ)
var n := 0
while f != null and not f.eof_reached():
	var l := f.get_line()
	if l.contains("[ERROR"):
		n += 1
		print("[sw11e-s4] debug-log ERROR: ", l)
return n
